export function clamp(value, low, high) {
  if (value < low) {
    return low;
  }
  if (value > high) {
    return high;
  }
  return value;
}

test("below range", () => { assert.equal(clamp(-1, 0, 10), 0); });
test("inside", () => { assert.equal(clamp(5, 0, 10), 5); });
test("above range", () => { assert.equal(clamp(11, 0, 10), 10); });
